// Custom Debug Log Viewer logic
function initDebugLogViewer() {
  const viewBtn = document.getElementById('viewDebugLogBtn');
  const modalTextarea = document.getElementById('debugLogsTextarea');
  const copyBtn = document.getElementById('copyDebugLogsBtn');

  console.log("[FACEBOOK-AUTO] initDebugLogViewer running. elements:", !!viewBtn, !!modalTextarea, !!copyBtn);

  if (viewBtn) {
    viewBtn.addEventListener('click', () => {
      console.log('[FACEBOOK-AUTO] View logs button clicked, fetching from storage...');
      chrome.storage.local.get(['postsCompleted'], (res) => {
        const logs = res.postsCompleted || [];
        if (typeof window.renderLogsModal === 'function') {
          window.renderLogsModal(logs);
        }
      });
    });
  }

  if (copyBtn) {
    copyBtn.addEventListener('click', () => {
      if (modalTextarea) {
        modalTextarea.select();
        modalTextarea.setSelectionRange(0, 99999);
        const textToCopy = modalTextarea.value;
        console.log("[FACEBOOK-AUTO] Copy logs button clicked. Text length:", textToCopy.length);

        const showSuccess = () => {
          const originalText = copyBtn.innerHTML;
          copyBtn.innerHTML = '<i class="bi bi-check-lg"></i> Copied!';
          copyBtn.classList.remove('btn-primary-custom');
          copyBtn.classList.add('btn-success');
          setTimeout(() => {
            copyBtn.innerHTML = originalText;
            copyBtn.classList.remove('btn-success');
            copyBtn.classList.add('btn-primary-custom');
          }, 2000);
        };

        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(textToCopy).then(() => {
            console.log("[FACEBOOK-AUTO] Copied successfully via Clipboard API");
            showSuccess();
          }).catch(err => {
            console.warn("[FACEBOOK-AUTO] Clipboard API rejected, trying execCommand:", err);
            try {
              const ok = document.execCommand('copy');
              if (ok) {
                console.log("[FACEBOOK-AUTO] Copied successfully via execCommand fallback");
                showSuccess();
              } else {
                throw new Error("execCommand copy returned false");
              }
            } catch (e) {
              console.error("[FACEBOOK-AUTO] Fallback copy also failed:", e);
              alert("Không thể copy tự động. Vui lòng nhấn Ctrl+A rồi nhấn Ctrl+C để copy thủ công.");
            }
          });
        } else {
          try {
            const ok = document.execCommand('copy');
            if (ok) {
              console.log("[FACEBOOK-AUTO] Copied successfully via execCommand");
              showSuccess();
            } else {
              throw new Error("execCommand copy returned false");
            }
          } catch (e) {
            console.error("[FACEBOOK-AUTO] Fallback copy failed:", e);
            alert("Không thể copy tự động. Vui lòng nhấn Ctrl+A rồi nhấn Ctrl+C để copy thủ công.");
          }
        }
      }
    });
  }
}

