// EXPORT/IMPORT LOGIC
document.addEventListener('DOMContentLoaded', function() {
  const dataExportImportBtn = document.getElementById('data-export-import');
  if (dataExportImportBtn) {
    dataExportImportBtn.addEventListener('click', function(e) {
      e.preventDefault();
      const modal = new bootstrap.Modal(document.getElementById('dataModal'));
      modal.show();
    });
  }

  const btnExportData = document.getElementById('btnExportData');
  if (btnExportData) {
    btnExportData.addEventListener('click', function() {
      chrome.storage.local.get(null, function(items) {
        // Strip out license info to be safe
        delete items.licenseKey;
        delete items.validationKey;
        
        const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(items));
        const downloadAnchorNode = document.createElement('a');
        downloadAnchorNode.setAttribute("href",     dataStr);
        downloadAnchorNode.setAttribute("download", "fb-auto-config.json");
        document.body.appendChild(downloadAnchorNode);
        downloadAnchorNode.click();
        downloadAnchorNode.remove();
        
        alert("Đã xuất dữ liệu thành công!");
      });
    });
  }

  const btnImportData = document.getElementById('btnImportData');
  if (btnImportData) {
    btnImportData.addEventListener('click', function() {
      const fileInput = document.getElementById('importDataFile');
      if (!fileInput.files || fileInput.files.length === 0) {
        alert("Vui lòng chọn file JSON để khôi phục.");
        return;
      }
      
      const file = fileInput.files[0];
      const reader = new FileReader();
      reader.onload = function(e) {
        try {
          const parsedData = JSON.parse(e.target.result);
          chrome.storage.local.set(parsedData, function() {
            alert("Đã khôi phục dữ liệu thành công! Extension sẽ tự động tải lại.");
            chrome.runtime.reload(); // Reload extension completely to apply new data
          });
        } catch(err) {
          alert("File không hợp lệ hoặc bị lỗi: " + err.message);
        }
      };
      reader.readAsText(file);
    });
  }
});

window.renderLogsModal = function(e) {
  const n = e.filter(item => item.response === "successful").length;
  const i = e.filter(item => item.response === "failed").length;
  const elSuccess = document.getElementById('successCount');
  const elFail = document.getElementById('failCount');
  if(elSuccess) elSuccess.innerText = n;
  if(elFail) elFail.innerText = i;
  
  const o = document.getElementById('logsList');
  if (o) {
    o.innerHTML = '';
    if (!e || e.length === 0) {
      o.innerHTML = '<p class="text-muted text-center py-4">Chưa có nhật ký đăng bài nào.</p>';
    } else {
      // Group by groupName
      const groups = {};
      e.forEach(item => {
        const gName = item.groupName || "Nhóm không tên";
        if (!groups[gName]) {
          groups[gName] = { total: 0, success: 0, items: [] };
        }
        groups[gName].total++;
        if (item.response === "successful") {
          groups[gName].success++;
        }
        groups[gName].items.push(item);
      });

      // Render each group
      for (const [gName, data] of Object.entries(groups)) {
        // Group Header
        const header = document.createElement("div");
        header.className = "list-group-item bg-dark text-white fw-bold d-flex justify-content-between align-items-center mt-3 border-0 rounded-top";
        header.innerHTML = `<span><i class="bi bi-folder2-open me-2"></i>${gName}</span> <span class="badge bg-primary fs-6">${data.success}/${data.total} Thành công</span>`;
        o.appendChild(header);

        // Group Items
        data.items.forEach((item, idx) => {
          let badgeClass = "bg-secondary", linkHtml = `<a href="${item.link}" target="_blank" class="text-white text-decoration-underline" style="word-break: break-all;">${item.link}</a>`;
          if ("successful" === item.response) {
            badgeClass = "bg-success";
            
          } else if ("failed" === item.response) {
            badgeClass = "bg-danger";
          } else if ("restricted" === item.response) {
            badgeClass = "bg-warning text-dark";
          }
          
          const r = document.createElement("li");
          const isLast = idx === data.items.length - 1;
          r.className = `list-group-item d-flex justify-content-between align-items-center ${badgeClass} text-white border-0 ${isLast ? 'rounded-bottom' : 'border-bottom border-light'}`;
          
          r.innerHTML = `
            <div class="d-flex flex-column" style="overflow: hidden; text-overflow: ellipsis; max-width: 80%;">
              <small>${linkHtml}</small>
            </div>
            <span class="badge bg-light text-dark rounded-pill">${"successful" === item.response ? "Thành công" : "Thất bại"}</span>
          `;
          o.appendChild(r);
        });
      }
    }
  }
  
  const modalEl = document.getElementById('logsModal');
  if (modalEl) {
     modalEl.classList.remove('d-none');
     try {
       const m = bootstrap.Modal.getOrCreateInstance(modalEl);
       m.show();
     } catch(err) {
       console.error("[FACEBOOK-AUTO] Modal error:", err);
     }
  }
};

// --- EXTENSION: Keyword Filtering, Clear Groups, CSV Export ---
document.addEventListener('DOMContentLoaded', () => {
  // Clear all groups
  const clearAllGroupsBtn = document.getElementById('clearAllGroupsBtn');
  if(clearAllGroupsBtn) {
    clearAllGroupsBtn.addEventListener('click', () => {
      if(confirm('Bạn có chắc muốn xóa tất cả nhóm khỏi danh sách?')) {
        document.getElementById('groupLinksContainer').innerHTML = '';
      }
    });
  }

  // Export CSV
  const exportGroupsCsvBtn = document.getElementById('exportGroupsCsvBtn');
  if(exportGroupsCsvBtn) {
    exportGroupsCsvBtn.addEventListener('click', () => {
      let links = [];
      const inputs = document.querySelectorAll('#groupLinksContainer input[type="text"]');
      inputs.forEach(input => {
        let val = input.value.trim();
        if(val) links.push(val);
      });
      if(links.length === 0) {
        alert('Không có link nhóm nào để xuất!');
        return;
      }
      let csvContent = "data:text/csv;charset=utf-8,\uFEFF" + links.join('\n');
      let encodedUri = encodeURI(csvContent);
      let link = document.createElement("a");
      link.setAttribute("href", encodedUri);
      link.setAttribute("download", "danh_sach_nhom.csv");
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    });
  }

  // Filter Keyword & Export
  const startKeywordExtractBtn = document.getElementById('startKeywordExtractBtn');
  if(startKeywordExtractBtn) {
    startKeywordExtractBtn.addEventListener('click', () => {
      const kwInput = document.getElementById('keywordFilterInput');
      const kw = kwInput ? kwInput.value.trim() : '';
      if(!kw) {
        alert('Vui lòng nhập từ khóa lọc nhóm!');
        return;
      }
      
      const spinner = document.getElementById('keywordExtractSpinner');
      startKeywordExtractBtn.disabled = true;
      if(spinner) spinner.classList.remove('d-none');
      
      chrome.tabs.query({active: true, currentWindow: true}, function(tabs) {
        const runExtract = (tId, shouldClose = false) => {
          chrome.tabs.sendMessage(tId, { action: "startKeywordExtract", keyword: kw });
          const poll = setInterval(() => {
            chrome.storage.local.get(["KeywordLinksArray", "KeywordExtractError"], (data) => {
              if (data.KeywordLinksArray) {
                clearInterval(poll);
                chrome.storage.local.remove(["KeywordLinksArray"]);
                if(spinner) spinner.classList.add('d-none');
                startKeywordExtractBtn.disabled = false;
                if (shouldClose) chrome.tabs.remove(tId);
                
                if(data.KeywordLinksArray.length === 0) {
                  alert('Không tìm thấy nhóm nào chứa từ khóa: ' + kw);
                  return;
                }
                
                let csvContent = "data:text/csv;charset=utf-8,\uFEFF" + data.KeywordLinksArray.join('\n');
                let encodedUri = encodeURI(csvContent);
                let link = document.createElement("a");
                link.setAttribute("href", encodedUri);
                link.setAttribute("download", "nhom_loc_" + kw + ".csv");
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
                alert('Xuất thành công ' + data.KeywordLinksArray.length + ' nhóm!');
              } else if (data.KeywordExtractError) {
                clearInterval(poll);
                chrome.storage.local.remove(["KeywordExtractError"]);
                if(spinner) spinner.classList.add('d-none');
                startKeywordExtractBtn.disabled = false;
                if (shouldClose) chrome.tabs.remove(tId);
                alert('Lỗi khi quét nhóm: ' + data.KeywordExtractError);
              }
            });
          }, 1000);
        };
        
        if (tabs && tabs.length > 0 && tabs[0].url && tabs[0].url.includes("facebook.com")) {
          runExtract(tabs[0].id, false);
        } else {
          startKeywordExtractBtn.innerHTML = '<i class="bi bi-funnel"></i> Đang mở tab ẩn...';
          chrome.tabs.create({url: "https://www.facebook.com/groups", active: false}, function(newTab) {
            chrome.tabs.onUpdated.addListener(function listener(tabId, info) {
              if (tabId === newTab.id && info.status === 'complete') {
                chrome.tabs.onUpdated.removeListener(listener);
                setTimeout(() => {
                  startKeywordExtractBtn.innerHTML = '<i class="bi bi-funnel"></i> Đang quét... <span class="spinner-border spinner-border-sm ms-1" role="status" aria-hidden="true"></span>';
                  runExtract(newTab.id, true);
                }, 3000);
              }
            });
          });
        }
      });
    });
  }
});
